"""
Trie木 & 01-Trie / Binary Trie (XOR最大化)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【FlatTrie (文字列・一般アルファベット)】
- insert(word): 文字列 word (整数のリスト) を登録
- count(word): 完全一致する単語の登録数を取得
- starts_with(prefix): prefix で始まる単語が存在するか判定

【BinaryTrie (01-Trie)】
- 非負整数の集合を2進数ビット木で管理。
- insert(x), erase(x): 数の追加・削除 (O(B), B=30等)
- max_xor(x): 集合内の要素 y に対し x ^ y を最大化する y (またはその最大値) を取得
"""

# https://github.com/ddfkit/acsampl/blob/main/tri.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class FlatTrie:
    def __init__(self,k=26):
        self.k=k;self.to=[[-1]*k];self.cnt=[0];self.stop=[0]
    def insert(self,word):
        u=0;self.cnt[u]+=1
        for c in word:
            nxt=self.to[u][c]
            if nxt<0:
                nxt=len(self.to);self.to.append([-1]*self.k)
                self.cnt.append(0);self.stop.append(0);self.to[u][c]=nxt
            u=nxt;self.cnt[u]+=1
        self.stop[u]+=1
    def count(self,word):
        u=0
        for c in word:
            u=self.to[u][c]
            if u<0:return 0
        return self.stop[u]

# https://github.com/ddfkit/acsampl/blob/main/tri.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class BinaryTrie:
    def __init__(self,bit=30):
        self.b=bit;self.to=[[-1,-1]];self.cnt=[0]
    def insert(self,x):
        u=0;self.cnt[u]+=1
        for i in range(self.b-1,-1,-1):
            bit=(x>>i)&1;nxt=self.to[u][bit]
            if nxt<0:nxt=len(self.to);self.to.append([-1,-1]);self.cnt.append(0);self.to[u][bit]=nxt
            u=nxt;self.cnt[u]+=1
    def max_xor(self,x):
        u=0;ans=0
        for i in range(self.b-1,-1,-1):
            bit=(x>>i)&1;target=bit^1
            if self.to[u][target]>=0 and self.cnt[self.to[u][target]]>0:
                ans|=(1<<i);u=self.to[u][target]
            else:u=self.to[u][bit]
        return ans

if __name__ == "__main__":
    t = FlatTrie(26)
    w1 = [ord(c) - 97 for c in "apple"]
    w2 = [ord(c) - 97 for c in "app"]
    t.insert(w1); t.insert(w2)
    assert t.count(w1) == 1 and t.count(w2) == 1

    bt = BinaryTrie(bit=5)
    for v in [3, 10, 5]: bt.insert(v)
    # x = 7 との最大 XOR: 7 ^ 10 = 13 (00111 ^ 01010 = 01101)
    assert bt.max_xor(7) == (7 ^ 10)
    print("tri.py: tests passed!")
